mapper.select:
select
d.TD_Name as tdName,

from SYS_T_Position p
left join SYS_T_Department d on p.TD_ID=d.TD_ID

    1=1
    
        and p.TD_ID=#{tdId}
    
    
        and p.TP_Name like concat('%',#{tpName},'%')
    
    
        and d.TO_ID=#{toId}
    


    
        order by p.${sortFiled} ${sortType}
    
    
        order by p.TP_Sort

select
count(*)
from SYS_T_Position mn
left join SYS_T_Department td on td.Td_Id=mn.Td_Id

    mn.TP_Code=#{tpCode}
    
        and mn.TP_ID!=#{tpId}
    
    and td.To_Id in (
    select To_Id from SYS_T_Department where Td_Id=#{tdId}
    )
